//! Constant-input nodes for the cost-per-constant cases (generated by a script in the
//! benchmark's scratch directory; the shape is the point, not the code).
//!
//! `config_s<N>` has N scalar constants (i64, f64, bool in turn); `config_m<N>` has N
//! constants of which every fourth is a `String` (a quarter, as Eidos's enum configs are
//! strings). Each node reads all of its constants, as a config struct would, and returns their
//! fold. The host pushes `tick` each tick; it is the only non-constant input.

#![allow(
    clippy::too_many_arguments,
    clippy::cast_possible_truncation,
    clippy::cast_precision_loss,
    clippy::cast_possible_wrap
)]

use daedalus::macros::node;
use daedalus::runtime::NodeError;

#[node(id = "config_s0", inputs("tick"), outputs("out"))]
pub fn config_s0(tick: i64) -> Result<i64, NodeError> {
    let sum = tick;
    Ok(sum)
}

#[node(
    id = "config_s8",
    inputs("tick", "c0", "c1", "c2", "c3", "c4", "c5", "c6", "c7"),
    outputs("out")
)]
pub fn config_s8(
    tick: i64,
    c0: i64,
    c1: f64,
    c2: bool,
    c3: i64,
    c4: f64,
    c5: bool,
    c6: i64,
    c7: f64,
) -> Result<i64, NodeError> {
    let mut sum = tick;
    sum = sum.wrapping_add(c0);
    sum = sum.wrapping_add(c1 as i64);
    sum = sum.wrapping_add(i64::from(c2));
    sum = sum.wrapping_add(c3);
    sum = sum.wrapping_add(c4 as i64);
    sum = sum.wrapping_add(i64::from(c5));
    sum = sum.wrapping_add(c6);
    sum = sum.wrapping_add(c7 as i64);
    Ok(sum)
}

