#[node(
    id = "config_m8",
    inputs("tick", "c0", "c1", "c2", "c3", "c4", "c5", "c6", "c7"),
    outputs("out")
)]
pub fn config_m8(
    tick: i64,
    c0: i64,
    c1: f64,
    c2: bool,
    c3: String,
    c4: f64,
    c5: bool,
    c6: i64,
    c7: String,
) -> Result<i64, NodeError> {
    let mut sum = tick;
    sum = sum.wrapping_add(c0);
    sum = sum.wrapping_add(c1 as i64);
    sum = sum.wrapping_add(i64::from(c2));
    sum = sum.wrapping_add(c3.len() as i64);
    sum = sum.wrapping_add(c4 as i64);
    sum = sum.wrapping_add(i64::from(c5));
    sum = sum.wrapping_add(c6);
    sum = sum.wrapping_add(c7.len() as i64);
    Ok(sum)
}

